{"command":"$ErrorActionPreference='SilentlyContinue'
"=== profiles ==="; Get-ChildItem "$env:USERPROFILE/workspace/profiles" -Force | Select-Object Name | Format-Table -AutoSize | Out-String
foreach($p in (Get-ChildItem "$env:USERPROFILE/workspace/profiles" -Directory -Force)){
  "=== profile: $($p.Name) ==="
  Get-ChildItem $p.FullName -Force | Select-Object Mode,Length,Name | Format-Table -AutoSize | Out-String -Width 200
}","description":"List DSH profiles and contents"}

{"command":"$ErrorActionPreference='SilentlyContinue'
$nm="$env:USERPROFILE/workspace/node_modules"
"=== broken/dangling reparse points in web/node_modules ==="
Get-ChildItem $nm -Force | Where-Object { $_.LinkType } | ForEach-Object {
  $t=$_.Target; $ok = if($t){ Test-Path $t } else { $false }
  if(-not $ok){ "DANGLING: $($_.Name) -> $t" }
}
"=== all non-dir (links) resolved count ==="
$links = Get-ChildItem $nm -Force | Where-Object { $_.LinkType }
"total links: $($links.Count)"
"=== @dsh-external ==="; Get-ChildItem "$nm\@dsh-external" -Force | Select-Object Mode,Name,Target | Format-Table -AutoSize | Out-String -Width 220
"=== @dsh-external target content ==="; Get-ChildItem "$nm\@dsh-external\dsh-super-injector" -Force | Select-Object Mode,Length,Name | Format-Table -AutoSize | Out-String -Width 200
"=== .dsh-module-fallback ==="; Get-ChildItem "$env:USERPROFILE/workspace/.dsh-module-fallback" -Force -Recurse -Depth 1 | Select-Object Mode,Length,FullName | Format-Table -AutoSize | Out-String -Width 220
"=== tmp link target ==="; (Get-Item "$env:[redacted-token]" -Force).Target","description":"Find broken junctions and inspect fallback dir"}

