{"command":"$ErrorActionPreference='SilentlyContinue'
"=== global @deepseek-ai in fnm install ==="; Get-ChildItem "$env:APPDATA/workspace/@deepseek-ai" -Force | Select-Object Mode,Name | Format-Table -AutoSize | Out-String -Width 200
"=== .pnpm store count ==="; (Get-ChildItem "$env:USERPROFILE/workspace/.pnpm" -Force -Directory).Count
"=== .pnpm sample ==="; Get-ChildItem "$env:USERPROFILE/workspace/.pnpm" -Force -Directory | Select-Object -First 15 Name | Format-Table -AutoSize | Out-String
"=== key pkg presence ==="
foreach($p in @('zod','cosmokit','schemastery','yaml','ws','express','sharp','node-pty','koffi','@deepseek-ai\dsh-web-app','@deepseek-ai\dsh-base','dsh-cost-meter','dsh-codearts-auth')){
  $path="$env:USERPROFILE/workspace/$p"
  $exists = Test-Path $path
  $pj = Join-Path $path 'package.json'
  $v = if(Test-Path $pj){ (Get-Content $pj -Raw | ConvertFrom-Json).version } else {'<no package.json>'}
  "$p : exists=$exists version=$v"
}
"=== .modules.yaml head ==="; Get-Content "$env:USERPROFILE/workspace/.modules.yaml" -TotalCount 30","description":"Verify key packages and pnpm store state"}

{"command":"$ErrorActionPreference='SilentlyContinue'
"=== Chrome profiles ==="
$paths=@("$env:LOCALAPPDATA/workspace/User Data","$env:LOCALAPPDATA/workspace/Chrome Beta\User Data","$env:LOCALAPPDATA/workspace/User Data","$env:LOCALAPPDATA/workspace/User Data")
foreach($p in $paths){ if(Test-Path $p){ "EXISTS: $p"; Get-ChildItem $p -Force | Select-Object Mode,LastWriteTime,Name | Format-Table -AutoSize | Out-String -Width 200 } else { "MISSING: $p" } }
"=== Extensions dirs ==="
foreach($p in $paths){ $e=Join-Path $p 'Default\Extensions'; if(Test-Path $e){ "=== $e ==="; Get-ChildItem $e -Force | Select-Object Name | Format-Table -AutoSize | Out-String } }","description":"Locate Chrome/Edge profiles and extensions"}

{"command":"$ErrorActionPreference='SilentlyContinue'
"=== CWS extension probe (Ride the Wave) ==="
try{
  $r = Invoke-WebRequest -Uri "https://example.com" -MaximumRedirection 0 -TimeoutSec 20 -UseBasicParsing
  "status: $($r.StatusCode)"; "location: $($r.Headers.Location)"
}catch{ "ERR: $($_.Exception.Message)"; if($_.Exception.Response){ "resp status: $([int]$_.Exception.Response.StatusCode)"; "resp location: $($_.Exception.Response.Headers.Location)" } }
"=== PowerShell version / webrequest redirect ==="; $PSVersionTable.PSVersion.ToString()
"=== CWS detail page reachable? ==="
try{ $r2=Invoke-WebRequest -Uri "https://example.com" -TimeoutSec 20 -UseBasicParsing; "detail status: $($r2.StatusCode) len=$($r2.Content.Length)" }catch{ "detail ERR: $($_.Exception.Message)" }","description":"Test Chrome Web Store CRX download path"}
